//! Translations, as a standalone crate.
//!
//! The locale files live here rather than inside a shell so they are an
//! artifact in their own right: a second Rust consumer (a worker writing a
//! user-facing error, a desktop client) links this crate, and a non-Rust one
//! (Swift, Kotlin) can have `locales/` converted to its own format without
//! digging it out of a wasm frontend.
//!
//! Almost everything below is generated by `i18n-keygen` from those files —
//! [`Key`], [`Locale`], the [`path`] helpers and [`translate`] and its
//! neighbours. What stays here by hand is the `i18n!` call they are written
//! against, the `leptos` adapter, and — behind the `format` feature — [`number`] and
//! [`plural_key`]: the locale-aware ways a shell writes an integer and picks the form of a
//! plural that goes with it.
//!
//! # Why this crate exposes functions rather than re-exporting `t!`
//!
//! rust-i18n's macros are crate-local by construction. `t!` expands to
//! `crate::_rust_i18n_t!(...)` — the *calling* crate's root — and `i18n!`
//! defines that macro as `pub(crate)`. The same goes for
//! `available_locales!()`, which expands to `crate::_rust_i18n_available_
//! locales()`. So a dependent crate cannot use them against this crate's
//! translations, however it imports them; what crosses the boundary is a plain
//! function call.
//!
//! That is also why the generated file is `include!`d at the crate root rather
//! than inside a `mod`: the wrappers in it call `t!` and `_rust_i18n_backend()`
//! themselves, and those only resolve inside the crate that called `i18n!`.
//!
//! [`rust_i18n::set_locale`] and [`rust_i18n::locale`] are the exception —
//! real functions over a global — and are re-exported unchanged.

#[macro_use]
extern crate rust_i18n;

i18n!("locales", fallback = ["en"]);

include!(concat!(env!("OUT_DIR"), "/i18n_generated.rs"));

#[cfg(feature = "leptos")]
pub mod reactive;

#[cfg(feature = "format")]
mod format;

#[cfg(feature = "format")]
pub use format::{
    Category, datetime, local_utc_offset_seconds, number, plural_categories, plural_category,
    plural_key,
};
pub use rust_i18n::{locale as current_locale, set_locale};

/// The best supported locale in a list of preferences, best first.
///
/// [RFC 4647] lookup rather than equality, because nothing hands out the bare
/// codes `locales/` is named with: a browser reports `hr-HR`, and so does a
/// POSIX `LANG=hr_HR.UTF-8` once `sys-locale` has converted it. Each candidate
/// is truncated at each `-` until something matches — `zh-Hant-TW` →
/// `zh-Hant` → `zh` — and the first that resolves wins. [`Locale::FALLBACK`]
/// when none does, because a user whose languages this product does not speak
/// still has to get a page.
///
/// POSIX punctuation is normalised away first — `_` to `-`, a `.encoding` or
/// `@modifier` suffix dropped. `sys-locale` has already done that on every path
/// measured; it is here because this function is public and its input need not
/// have come from there.
///
/// Pure, and that is the point: the whole algorithm is table-testable without a
/// platform, and [`from_system`] is a three-line shim that feeds it one. See
/// ADR 0015 for why this is a lookup rather than `split('-').next()`.
///
/// [RFC 4647]: https://www.rfc-editor.org/rfc/rfc4647
#[must_use]
pub fn negotiate<I, S>(preferences: I) -> Locale
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    for preference in preferences {
        // `_` is the POSIX subtag separator and `-` the BCP 47 one; a POSIX locale
        // may also carry `.UTF-8` or `@euro`, which name an encoding and a variant
        // rather than a language.
        let normalized = preference
            .as_ref()
            .split(['.', '@'])
            .next()
            .unwrap_or_default()
            .replace('_', "-");

        let mut candidate = Some(normalized.as_str());
        while let Some(tag) = candidate {
            if let Some(locale) = supported(tag) {
                return locale;
            }
            // Drop the last subtag and ask again: somebody asking for `hr-HR` is
            // asking for Croatian, and a product shipping only `hr` should answer.
            candidate = tag.rfind('-').map(|cut| &tag[..cut]);
        }
    }

    Locale::FALLBACK
}

/// A locale code, matched without regard to ASCII case.
///
/// Deliberately not [`Locale::try_from`], which is a `match` on the code exactly
/// as `locales/` spells it. A script subtag is conventionally titlecase, so a
/// product with `locales/zh-Hant/` would miss every `zh-hant` a system hands
/// over; folding the candidate instead would miss every `zh-Hant`. Ignoring case
/// is the only version that is right in both directions.
fn supported(code: &str) -> Option<Locale> {
    Locale::ALL
        .iter()
        .copied()
        .find(|locale| locale.as_str().eq_ignore_ascii_case(code))
}

/// The best supported locale for the system this is running on.
///
/// Behind the `detect` feature, because a worker that links this crate for one
/// user-facing string has no business acquiring platform detection.
///
/// `sys-locale` reads POSIX `LANG`/`LC_ALL`, macOS `AppleLanguages` — which is
/// *not* an environment variable, so the hand-rolled version of this function is
/// wrong on the platform it looks most correct on — Windows, and
/// `navigator.languages` on wasm. `get_locales` rather than `get_locale`: it
/// returns the preferences in descending order, and somebody who lists Croatian
/// second should get Croatian when this product cannot speak their first.
///
/// Whatever calls this must also call [`set_locale`]. The returned `Locale` is
/// what a shell holds and passes to [`translate`]; the global is what anything
/// reaching a translation without one reads, and the two drifting apart shows as
/// one language in some of the window and another in the rest.
#[cfg(feature = "detect")]
#[must_use]
pub fn from_system() -> Locale {
    negotiate(sys_locale::get_locales())
}

/// [`from_system`], made current for the global as well.
///
/// The one-line form for a shell that holds a plain `Locale`: reading the system
/// and making rust-i18n's global agree are separable in principle and never
/// separate in practice, and a shell that does the first without the second
/// renders whatever reaches a translation without an explicit locale in the other
/// language. Handing back the `Locale` it set means a struct field can be
/// initialised with one call and no ceremony.
///
/// The web shell does not use this: it has a signal to write too, and names that
/// three-way pairing `apply_locale`.
#[cfg(feature = "detect")]
#[must_use]
pub fn adopt_system_locale() -> Locale {
    let locale = from_system();
    set_locale(locale.as_str());
    locale
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fallback locale is written twice — once as `i18n!`'s literal, once
    /// as the generator's `.fallback(..)` — and nothing makes them agree.
    ///
    /// The generated `const _: () = assert!(..)` cannot check this: it only
    /// compares two values the generator derived from the same setting, so it
    /// holds however wrong that setting is. rust-i18n keeps the literal in a
    /// private `static`, which const evaluation may not read — but a test may,
    /// so the check lives here instead of at compile time.
    ///
    /// Left unchecked, a disagreement is close to invisible: lookups fall back
    /// to a locale with no translations and every key renders as itself.
    #[test]
    fn the_i18n_macro_and_the_generator_agree_on_the_fallback() {
        assert_eq!(
            _RUST_I18N_FALLBACK_LOCALE,
            Some(&[FALLBACK_LOCALE][..]),
            "`i18n!`'s `fallback` and i18n-keygen's `.fallback(..)` disagree"
        );
    }

    /// The build script warns about drift; this fails on it. Warnings scroll
    /// past, and a missing translation silently renders the fallback language
    /// in the middle of an otherwise translated page.
    ///
    /// `Key::CATALOG` rather than `Key::ALL`, and the difference is exactly one entry
    /// wide: `Key::ALL` names `apples` once, and `apples` is not a string any locale
    /// defines, so iterating variants would report the plural family untranslated forever.
    /// Categories are checked where the rules are known — [`every_category_a_locale_has_translates`].
    #[test]
    fn every_locale_translates_every_key() {
        let mut missing = Vec::new();

        for locale in Locale::ALL {
            for (key, family) in Key::CATALOG {
                if Key::PLURAL_FAMILIES.contains(family) {
                    continue;
                }

                if try_translate(key, locale).is_none() {
                    missing.push(format!("{locale}: {key}"));
                }
            }
        }

        assert!(missing.is_empty(), "untranslated keys: {missing:#?}");
    }

    /// The CLDR data slice covers the locales the catalog ships and holds no one else's (ADR 0021).
    ///
    /// This is the invariant that makes the size win in ADR 0021 permanent rather than a
    /// one-off measurement. It is deliberately not a list of locale codes typed into this
    /// file or into the recipe: `i18n_data::locale_codes` asks the generated provider which
    /// identifiers its own tries contain, so the two sides of the comparison are produced by
    /// two different generators from two different inputs — `crates/i18n/locales/**/*.toml`
    /// for `Locale::ALL`, CLDR for the data. A locale added to the catalog without
    /// regenerating the data fails here, naming the locale; data for a locale the catalog no
    /// longer ships fails here too, because that payload is dead weight in every binary that
    /// ships this crate, and dead locales are how the saving in ADR 0021 would quietly go
    /// back again while every formatter still returned `Ok`.
    ///
    /// The backward direction is not set equality, and writing it as equality would encode a
    /// wrong idea of what a slice is: asking for `en` and `hr` yields some 120 more
    /// identifiers, because CLDR keeps English apart by region (`en-001`, `en-AU`, …) and
    /// lists the locales that inherit from the ones asked for (`hr-BA`, and `hi-Latn`, whose
    /// chain runs `hi-Latn → en-IN → en-001 → en`). So the rule is that every identifier in
    /// the slice must fall back — by the fallbacker the slice carries itself — to a locale the
    /// catalog ships. That admits all of CLDR's decomposition of English and rejects `de`,
    /// which falls back to the root and to nothing else. `und` is exempt in both directions:
    /// every chain ends there, and no catalog file is written for it.
    ///
    /// Watched to fail by adding `locales/common/de.toml` with one key: this test reports
    /// `de` as missing from the data, and `every_locale_translates_every_key` reports the
    /// same locale as untranslated, which is the other half of the same omission.
    #[cfg(feature = "format")]
    #[test]
    fn the_icu_data_slice_covers_the_locales_the_catalog_ships() {
        let shipped: std::collections::BTreeSet<&str> =
            Locale::ALL.iter().copied().map(Locale::as_str).collect();
        let sliced = i18n_data::locale_codes();

        let missing: Vec<&str> = shipped
            .iter()
            .filter(|locale| !sliced.contains(**locale))
            .copied()
            .collect();
        let foreign: Vec<&str> = sliced
            .iter()
            .map(String::as_str)
            .filter(|locale| *locale != "und")
            .filter(|locale| {
                !i18n_data::fallback_chain(locale)
                    .iter()
                    .any(|step| shipped.contains(step.as_str()))
            })
            .collect();

        assert!(
            missing.is_empty() && foreign.is_empty(),
            "the CLDR data slice and crates/i18n/locales disagree: \
             shipped but not in the slice: {missing:?}; in the slice but not in the fallback \
             chain of any shipped locale: {foreign:?}. \
             Run `just i18n::generate-data` and commit crates/i18n-data/src/data."
        );
    }

    /// Every plural category a locale's own rules give it, translated.
    ///
    /// The generator refuses a catalog that gets this wrong (`plurals_match_cldr`), so this
    /// test cannot fail unless the two halves of ADR 0018 disagree about CLDR — which is
    /// precisely the failure worth having a second witness for, since it arrives as a
    /// missing word on screen rather than as a build error.
    #[cfg(feature = "format")]
    #[test]
    fn every_category_a_locale_has_translates() {
        let mut missing = Vec::new();

        for locale in Locale::ALL {
            for family in Key::PLURAL_FAMILIES {
                for category in plural_categories(*locale) {
                    let key = format!("{family}.{}", category.as_str());

                    if try_translate(&key, locale).is_none() {
                        missing.push(format!("{locale}: {key}"));
                    }
                }
            }
        }

        assert!(
            missing.is_empty(),
            "untranslated plural categories: {missing:#?}"
        );
    }

    #[test]
    fn locale_codes_round_trip() {
        for locale in Locale::ALL {
            assert_eq!(Locale::try_from(locale.as_str()), Ok(*locale));
        }

        assert_eq!(Locale::try_from("klingon"), Err(UnsupportedLocale));
    }

    #[test]
    fn splits_a_locale_prefix_off_a_path() {
        use path::split;

        assert_eq!(split("/en/counter"), (Some(Locale::En), "/counter"));
        assert_eq!(
            split("/en/counter/split"),
            (Some(Locale::En), "/counter/split")
        );
        assert_eq!(split("/en"), (Some(Locale::En), "/"));
        assert_eq!(split("/en/"), (Some(Locale::En), "/"));

        // Not a locale, so the path is its own: `/counter` is a page, not a
        // language, and this is the distinction the router cannot make.
        assert_eq!(split("/counter"), (None, "/counter"));
        assert_eq!(split("/"), (None, "/"));
        assert_eq!(split(""), (None, ""));
    }

    #[test]
    fn rewrites_a_path_into_another_locale() {
        use path::with_locale;

        // The fallback is unprefixed, so switching to it removes the segment —
        // which means these expectations swap with the fallback locale. In
        // `fishing` the fallback is `hr`; here it is `en` (see build.rs), and
        // this test is where that choice is paid for.
        assert_eq!(with_locale("/hr/counter", Locale::En), "/counter");
        assert_eq!(with_locale("/hr", Locale::En), "/");
        assert_eq!(with_locale("/counter", Locale::En), "/counter");

        assert_eq!(with_locale("/counter", Locale::Hr), "/hr/counter");
        assert_eq!(with_locale("/", Locale::Hr), "/hr");
        assert_eq!(with_locale("/hr/counter", Locale::Hr), "/hr/counter");

        // Round trip: every locale, there and back.
        for locale in Locale::ALL {
            let there = with_locale("/counter/detail", *locale);
            assert_eq!(with_locale(&there, Locale::FALLBACK), "/counter/detail");
        }
    }

    /// The keys here are not in the locale files, so `translate` hands the key
    /// back unchanged — which makes it the interpolation template, and keeps
    /// these tests independent of the actual copy.
    #[test]
    fn interpolates_named_arguments() {
        assert_eq!(
            translate_with!("%{count} fish", Locale::FALLBACK, count = 3),
            "3 fish"
        );

        // Anything `Display`, not only `&str`.
        assert_eq!(
            translate_with!(
                "%{name} caught %{count}",
                Locale::FALLBACK,
                name = "Ana",
                count = 2u8
            ),
            "Ana caught 2"
        );

        // The same placeholder more than once.
        assert_eq!(
            translate_with!("%{a} and %{a}", Locale::FALLBACK, a = "x"),
            "x and x"
        );

        // No arguments at all is still valid.
        assert_eq!(translate_with!("plain", Locale::FALLBACK), "plain");
    }

    #[test]
    fn interpolates_with_format_specifiers() {
        assert_eq!(
            translate_with!("no %{sn}", Locale::FALLBACK, sn = 123 => "{:08}"),
            "no 00000123"
        );

        assert_eq!(
            translate_with!("%{ratio}", Locale::FALLBACK, ratio = 2.0 / 3.0 => "{:.2}"),
            "0.67"
        );

        // Specifier and plain argument in one call, and a trailing comma.
        assert_eq!(
            translate_with!(
                "%{name}: %{sn}",
                Locale::FALLBACK,
                name = "lure",
                sn = 7 => "{:03}",
            ),
            "lure: 007"
        );
    }

    /// The shapes a real system hands over, none of which is a bare locale code.
    ///
    /// `hr_HR.UTF-8` is POSIX, `hr-HR` is what a browser reports, and `hr` is
    /// what `locales/` is named. Equality would resolve exactly one of the three.
    #[test]
    fn negotiation_reduces_a_system_locale_to_a_supported_one() {
        assert_eq!(negotiate(["hr_HR.UTF-8"]), Locale::Hr);
        assert_eq!(negotiate(["hr-HR"]), Locale::Hr);
        assert_eq!(negotiate(["hr"]), Locale::Hr);
        assert_eq!(negotiate(["en_GB"]), Locale::En);
        // POSIX may carry a variant as well as an encoding.
        assert_eq!(negotiate(["hr_HR.UTF-8@euro"]), Locale::Hr);
    }

    /// A language this product does not speak still has to render something.
    #[test]
    fn negotiation_falls_back_rather_than_failing() {
        assert_eq!(negotiate(["de-DE"]), Locale::FALLBACK);
        assert_eq!(negotiate(["klingon"]), Locale::FALLBACK);
        assert_eq!(negotiate([""]), Locale::FALLBACK);
        assert_eq!(negotiate(std::iter::empty::<&str>()), Locale::FALLBACK);
    }

    /// The list is preferences in descending order, so the answer is the first
    /// *supported* one rather than the first one.
    #[test]
    fn negotiation_walks_past_preferences_this_product_cannot_speak() {
        assert_eq!(negotiate(["de-DE", "hr-HR", "en"]), Locale::Hr);
        assert_eq!(negotiate(["de", "fr", "en-US"]), Locale::En);
    }

    /// Case is not part of the answer.
    ///
    /// A script subtag is conventionally titlecase (`zh-Hant`) while a system
    /// may send any case at all, so matching exactly would be wrong in one
    /// direction whichever way the codes happen to be spelled. Neither locale
    /// here has a script subtag — that is the case this guards against arriving.
    #[test]
    fn negotiation_ignores_case() {
        assert_eq!(negotiate(["HR"]), Locale::Hr);
        assert_eq!(negotiate(["hr_hr.utf-8"]), Locale::Hr);
        assert_eq!(negotiate(["EN-us"]), Locale::En);
    }

    /// The half of the pairing a shell cannot see.
    ///
    /// `adopt_system_locale` exists so that reading the system and making
    /// rust-i18n's global agree cannot be done separately. Whatever the machine
    /// running this says, the global must end up holding what the call returned;
    /// if it does not, a shell renders its own text in one language and anything
    /// reaching a translation without an explicit locale in another. Env-free on
    /// purpose — the assertion is a relation between two outputs, not a claim
    /// about what the system speaks.
    #[cfg(feature = "detect")]
    #[test]
    fn adopting_the_system_locale_moves_the_global_with_it() {
        // A code no `locales/` directory can produce, so the assertion cannot pass by
        // the global already holding what the system was going to say.
        set_locale("zz");
        let adopted = adopt_system_locale();
        assert_eq!(&*current_locale(), adopted.as_str());
    }
}
